changeSet.sql:
ALTER TABLE clinlims.micro_ast_run ADD CONSTRAINT micro_ast_run_attempt_type_chk CHECK (attempt_type IN ('ORIGINAL', 'REPEAT', 'RETEST')); ALTER TABLE clinlims.micro_ast_run ADD CONSTRAINT micro_ast_run_method_chk CHECK (method IS NULL OR method IN ('MIC', 'ZONE')); ALTER TABLE clinlims.micro_ast_run ADD CONSTRAINT micro_ast_run_attempt_source_chk CHECK ( (attempt_type = 'ORIGINAL' AND source_run_id IS NULL) OR (attempt_type IN ('REPEAT', 'RETEST') AND source_run_id IS NOT NULL AND length(trim(attempt_reason)) > 0) );
UPDATE clinlims.micro_ast_run target SET reportable = true WHERE target.status = 'REVIEWED' AND 1 = ( SELECT count(*) FROM clinlims.micro_ast_run sibling WHERE sibling.isolate_id = target.isolate_id AND sibling.status = 'REVIEWED' );
CREATE UNIQUE INDEX uq_micro_ast_run_reportable ON clinlims.micro_ast_run (isolate_id) WHERE reportable = true AND status = 'REVIEWED';

rollback.sql:
ALTER TABLE clinlims.micro_ast_run DROP CONSTRAINT micro_ast_run_attempt_source_chk;
ALTER TABLE clinlims.micro_ast_run DROP CONSTRAINT micro_ast_run_method_chk;
ALTER TABLE clinlims.micro_ast_run DROP CONSTRAINT micro_ast_run_attempt_type_chk;
